import {useCallback, useState} from 'react';
import {ActivityIndicator, View} from 'react-native';
import TextCM from '../../components/Text';
import {useFocusEffect, useNavigation} from '@react-navigation/native';
import {Color, Font, NavigationName} from '../../../constants';
import {Icon, List, MenuGroup, MenuItem} from '@ui-kitten/components';
import {useTicketServices} from '../../../hooks/apiHooks/useAPI';
import {IServicesHome, Modeler} from './helper';
import {useAppSelector} from '../../../hooks/useRedux';
import {useTranslation} from 'react-i18next';
import Toast from 'react-native-toast-message';

type Props = {
  onClose: () => void;
};

const CreateNewScreenOfQDTHA = ({onClose}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const [listServices, setListServices] = useState<IServicesHome[]>([]);

  const [loading, setLoading] = useState(true);
  const {dataAccount} = useAppSelector(state => state.account);
  const TicketService = useTicketServices();

  const getServiceOfTHADS = async (serviceCode: string) => {
    try {
      setLoading(true);
      const roleIds = dataAccount?.roles?.map((r: any) => r.id).join(',');
      const body = {
        serviceCode: serviceCode,
        textSearch: null,
        roleIds: roleIds,
      };
      const params = {
        page: 0,
        size: 1000000,
      };
      const dataResp = await TicketService.getListServives(body, params);
      return dataResp?.content?.[0] || [];
    } catch (error) {
    } finally {
      setLoading(false);
    }
  };

  const getServiceCode = async () => {
    const dataResp = await TicketService.getListServiceCodeOfQDTHA();
    if (dataResp) {
      const values = await Promise.all(
        dataResp?.map((item: any) =>
          getServiceOfTHADS(item['textField_input-2']),
        ),
      );
      if (values && values?.length) {
        setListServices(values?.filter((item: any) => item)?.flat());
      }
    } else {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: 'Có lỗi xảy ra khi lấy dịch vụ',
      });
    }
  };

  useFocusEffect(
    useCallback(() => {
      getServiceCode();
    }, []),
  );
  const handleCreate = (item: Modeler) => {
    onClose();
    navigation.navigate(NavigationName.CreateTicketScreen, {
      dataTicket: item,
      actionTicketFrom: 'QDTHA',
    });
  };
  return (
    <>
      {!loading ? (
        <List
          data={listServices}
          renderItem={({item}) => (
            <MenuGroup
              initiallyExpanded={listServices?.length === 1}
              title={props => <TextCM {...props}>{item?.serviceName}</TextCM>}>
              {item?.modelers?.map((itemModeler: Modeler) => (
                <MenuItem
                  onPress={() => handleCreate(itemModeler)}
                  title={props => (
                    <TextCM
                      {...props}
                      style={{
                        fontSize: 14,
                        color: Color.TextPrimary,
                        fontFamily: Font.InterRegular400,
                        flex: 1,
                        marginLeft: 16,
                      }}>
                      {itemModeler?.flowName}
                    </TextCM>
                  )}
                  accessoryRight={
                    <Icon
                      name="arrow-ios-forward-outline"
                      fill={Color.TextPrimary}
                      width={20}
                      height={20}
                    />
                  }
                />
              ))}
            </MenuGroup>
          )}
          keyExtractor={(item, index) => index.toString()}
          ListEmptyComponent={() => (
            <View
              style={{
                alignItems: 'center',
                justifyContent: 'center',
                height: 200,
              }}>
              <TextCM>{t('CM.emptyData')}</TextCM>
            </View>
          )}
        />
      ) : (
        <ActivityIndicator size="small" color={Color.BgPrimary} />
      )}
    </>
  );
};

export default CreateNewScreenOfQDTHA;
